<script>
 import RegionState from './RegionState.svelte';import {createConfiguration} from '../lib/configuration.svelte';
 import {submitSingleGeneration,singleGenerationConfigured} from '../services/single-generation.js';import {selectVersion} from '../services/editor.js';import {navigate} from '../app/shell.svelte';import {editorUrl} from '../lib/router.ts';import {ratios,chooseRatio,swapRatio,ratioLabel,defaultOrientation} from '../lib/ratio.ts';import {tasks} from '../stores/tasks.svelte';
 import {executionPrefs} from '../stores/execution-prefs.svelte';
 import NewProductMode from './NewProductMode.svelte';
 import Segmented from '../ui/Segmented.svelte';
 let generationTab=$state('new-product');
 import {normalizeEdit} from '../preview-cache';
 import {Sparkles,ArrowUpRight} from 'lucide-svelte';import {studio,asset,run,updateProject,save,notify,referencePreview,goSettings,importImages,dropImages,current,selectProject,select} from '../studio.svelte';import {api,clone,isTeam} from '../api';import {estimate,money} from '../cost';
 let modelChosen=$state(false);
 let sourceMode=$state('reference'),prompt=$state(''),modelId=$state(''),resolution=$state('1K'),ratio=$state('1:1'),inputTokens=$state(1000),outputTokens=$state(1000);
 const configuration=createConfiguration(singleGenerationConfigured);const configured=$derived(configuration.state.configured);
 let orientation=$state('landscape'),submitting=$state(false),taskId=$state(null),submissionStatus=$state('');const activeTask=$derived(taskId&&['queued','running','waiting','submitted'].includes(tasks.byId[taskId]?.state));let actualRatio=$derived(ratioLabel({ratio,orientation}));
 let models=$derived(studio.catalog?.models||[]),model=$derived(models.find(m=>m.id===modelId)||models[0]);
 $effect(()=>{if(!modelChosen&&executionPrefs.status==='ready'&&models.some(m=>m.id===executionPrefs.imageModel))modelId=executionPrefs.imageModel;});
 $effect(()=>{if(model){if(!modelId)modelId=model.id;if(!model.resolutions.includes(resolution))resolution=model.resolutions[0];if(!model.ratios.includes(actualRatio)){ratio='1:1';orientation='landscape';}}});
 $effect(()=>{const id=model?.id;if(studio.mode==='generate'&&generationTab==='standard'&&id)void configuration.load(id);return()=>configuration.cancel();});
 let cost=$derived(model?estimate(model,resolution,inputTokens,outputTokens):null);
 async function generate(){if(submitting||activeTask)return;submitting=true;submissionStatus='';try{const result=await submitSingleGeneration({sourceMode,prompt,model:model.id,resolution,ratio:{ratio,orientation}});taskId=result?.task?.id||null;submissionStatus=result?.confirmation?'进度、确认操作和结果会在右侧对话的同一执行行更新。':result?.task?'已提交，可在右侧对话查看进度和撤销结果':'未提交，请查看对话中的错误提示';}catch(error){studio.error=error.message;}finally{submitting=false;}}
 async function openVersion(version){navigate(editorUrl(studio.aid));await selectVersion(version.id);}
 function chooseGenerationRatio(value){const state=chooseRatio(value);ratio=state.ratio;orientation=state.orientation;}
 function swapGenerationRatio(){if(ratio==='1:1')return;orientation=swapRatio({ratio,orientation}).orientation;}
 async function pasteReference(event){
  if(generationTab!=='standard'||studio.mode!=='generate'||studio.busy)return;
  const files=[...(event.clipboardData?.files||[])].filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type));if(!files.length)return;
  event.preventDefault();const file=files[0];try{await dropImages([file]);studio.mode='generate';const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');const pasted=current()?.assets.find(a=>a.sha256===hash&&!a.trashed);if(pasted)select(pasted.id,true);sourceMode='reference';}catch(e){studio.error=e.message;}
 }
</script>
<svelte:window onpaste={pasteReference}/>
<div class="generation-scroll">
<div class="generation-mode-tabs"><Segmented label="生成方式" options={[{value:'new-product',label:'新品套图'},{value:'standard',label:'单图生成'}]} value={generationTab} onchange={value=>{generationTab=value;if(value==='new-product')studio.workflowChat=null;}}/></div>
{#if generationTab==='new-product'}<NewProductMode active={studio.mode==='generate'}/>{:else}<div class="legacy-editor"><div class="workflow-panel generation-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>生成图片</h1><span>{sourceMode==='text'?'纯文本生图':'参考图生图'} · {model?.id?.startsWith('GPT-Image')?'Poe':'Google'}</span></div><div class="generation-layout"><div class="generation-reference"><div class="segmented" role="group" aria-label="生图方式"><button class:active={sourceMode==='reference'} onclick={()=>sourceMode='reference'}>参考图片</button><button class:active={sourceMode==='text'} onclick={()=>sourceMode='text'}>纯文本生图</button></div>{#if sourceMode==='reference'&&asset()}<img src={referencePreview()} alt="参考图片"/><span>{asset()?.name}</span><div class="generation-history">{#each [...(asset()?.versions||[])].filter(v=>v.kind==='generated').reverse() as v}<button class="line-button" onclick={()=>openVersion(v)}>{new Date(v.createdAt*1000).toLocaleDateString()}<ArrowUpRight size={13}/></button>{/each}</div>{:else}<p>{sourceMode==='text'?'只发送文字要求，不发送参考图片。':'粘贴图片（Ctrl+V），或导入参考图片。'}</p>{/if}<button class="line-button" onclick={async()=>{await importImages(false);studio.mode='generate';sourceMode='reference';}}>导入 / 更换参考图</button><p class="hint">可直接在此页按 Ctrl+V 粘贴图片。</p></div><div class="generation-form">{#if !model}<RegionState compact state="empty" title="没有可用的生图模型" message="请检查主机的模型配置。"/>{:else if configuration.state.status==='idle'||configuration.state.status==='loading'}<RegionState compact state="loading" title="正在读取生图配置"/>{:else if configuration.state.status==='error'}<RegionState compact state="error" title="无法读取生图配置" message={configuration.state.error} onretry={()=>configuration.load(model.id)}/>{:else if !configured}<RegionState compact state="empty" title={'尚未配置 '+(model.id.startsWith('GPT-Image')?'Poe':'Google')+' API'}/>{/if}{#if model?.id?.startsWith('GPT-Image')}<p class="hint">Poe 按点数计费，实际尺寸以生成结果为准。需要固定像素时，请在导出页设置。</p>{/if}<label>生成要求<textarea aria-label="图片生成要求" bind:value={prompt} placeholder="描述你想生成的图片。" rows="6"></textarea></label><label>生图模型<select aria-label="生图模型" bind:value={modelId} onchange={()=>modelChosen=true}>{#each models as m}<option value={m.id}>{m.name}</option>{/each}</select></label><div class="field-grid"><label>生成分辨率<select aria-label="生成分辨率" bind:value={resolution}>{#each model?.resolutions||[] as r}<option>{r}</option>{/each}</select></label><div class="generation-ratio"><span>宽高比</span><div class="ratio-options" role="group" aria-label="生成宽高比">{#each ratios as option}<button class:active={ratio===option} aria-pressed={ratio===option} disabled={submitting||activeTask||!model?.ratios.includes(ratioLabel(chooseRatio(option)))} onclick={()=>chooseGenerationRatio(option)}>{ratio===option?actualRatio:option}</button>{/each}<button aria-label="交换生成横竖" disabled={ratio==='1:1'||submitting||activeTask||!model?.ratios.includes(ratioLabel(swapRatio({ratio,orientation})))} onclick={swapGenerationRatio}>⇄</button></div></div></div><div class="cost-line"><span>预计费用</span><b>{cost===null?'费用待确认':money(cost,studio.currency,studio.exchangeRate)}</b></div><button class="primary full" disabled={submitting||activeTask||!!studio.busy||!prompt.trim()||!model||!configured||(sourceMode==='reference'&&!asset())} onclick={generate}><Sparkles size={16}/>{submitting?'正在提交…':activeTask?'生成中…':'生成图片'}</button><p class="hint" role="status">{submissionStatus}</p>{#if configuration.state.status==='ready'&&!configured}{#if isTeam}<p class="hint">请联系主机管理员配置 {model?.id?.startsWith('GPT-Image')?'Poe':'Google'} API。</p>{:else}<button class="text-button" onclick={()=>goSettings('generate')}>前往设置配置 {model?.id?.startsWith('GPT-Image')?'Poe':'Google'} API<ArrowUpRight size={13}/></button>{/if}{/if}</div></div></div>
</div>{/if}
</div>




<style>.generation-scroll{height:100%;min-height:0;overflow:auto;overscroll-behavior:contain}.generation-mode-tabs{padding:20px 32px 0;max-width:1760px;margin:0 auto}.legacy-editor{height:auto}.generation-ratio{display:flex;flex-direction:column;gap:8px;font-size:12px}.ratio-options{display:flex;flex-wrap:wrap;gap:2px;border:1px solid var(--border);padding:2px}.ratio-options button{min-height:30px;min-width:34px;padding:4px;font-size:12px}.ratio-options button.active{color:var(--accent);background:var(--accent-soft)}.ratio-options button:focus-visible{outline:2px solid var(--focus);outline-offset:1px}</style>
